using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class OriginalComparisonTopologyDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalComparisonTopology.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original scalar topology and local optimal budgets",
        H("Original scalar topology and local optimal budgets"), Blocks(
            Describe.Lean(DescribeId.Create("pure-comparison-continuous"), DeclarationHandle.Create(Owner + "pure_comparison_continuous"),
                H("Joint continuity on the whole original pure-pair carrier"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Strict positivity, generation and pure reciprocity give continuity of (p,q) mapped to T(p,q) on the entire product P times P with its norm subspace topology. The uniform original row bound controls both variables after exchanging pure endpoints. This consumed helper supplies the separated-pure-pair gap construction and the whole-limit calibration proof. It supplies no independent escape witness and assumes no mixed reciprocity, label injectivity or singleton confirmer fiber."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-uniform-comparison"), DeclarationHandle.Create(Owner + "original_uniform_comparison"),
                H("All mixed inputs of every pure row"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Strict positivity and generation give one finite L>0 such that abs(T(p,x)-T(p,y))<=L norm(x-y) for every original pure p and all original mixed x,y in K. This consumed helper directly uses the original frozen CommonOldExclusionConfirmation.comparison_lipschitz owner, enlarging its bound to a positive constant. It provides no independent new mathematical content or escape witness. Neither EB nor PR nor Inj is needed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-scale-axis-bound"), DeclarationHandle.Create(Owner + "original_scale_axis_bound"),
                H("Universal actual scale-to-axis estimate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under closedness, strict positivity, generation, EB and pure PR, one L>0 works at every original pure p and every complete chart a. A positive common scale t<=1/2 has extensionBudget(a,v)=1/(2t) in every unit direction and 2t<=L norm(a(v)-a(-v)). These are the same actual comparison coefficient and original optimal budget, using all mixed inputs of the original scale owner."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("original-bounded-budget-noncollapse"), DeclarationHandle.Create(Owner + "original_bounded_budget_noncollapse"),
                H("Finite budget on arbitrary whole-P label sets"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("For any set U of original pure labels and real B>0, assume every actual chart and unit direction at every p in U has extensionBudget<=B. There is a single delta>0 with delta<=diam(D(p)) for all p in U, explicitly delta=1/(B L) for the universal comparison bound. U is an arbitrary subset of the entire P; it may be a neighborhood containing labels outside P0. This is the noncollapse direction of the local-budget argument. The reverse implication is provided by original_noncollapse_bounded_budget, and original_local_budget_iff combines them in open neighborhoods of all P."))), DescribeRole.Theorem),
            new DocumentBlock.Section(H("Every actual diameter collapse makes budgets diverge"), Blocks(
                Paragraph(Text("Assume closedness, strict positivity, generation, general EB and pure PR. Let pn be any sequence of original pure labels whose full exclusion diameters tend to zero. Choose arbitrary complete original charts a(n) and any unit coordinate v(n) in each, with dimensions allowed to vary. Then their actual extensionBudget(a(n),v(n)) tends to positive infinity. The universal scale-to-diameter estimate gives 1<=budget(n) L diam(D(pn)); no finite bound can persist along the sequence. This argument does not assume EB3 or label convergence, restrict labels to P0, or replace the original budget with a reciprocal definition.")))),
            Describe.Lean(DescribeId.Create("original-noncollapse-bounded-budget"), DeclarationHandle.Create(Owner + "original_noncollapse_bounded_budget"),
                H("Every whole-diameter lower bound gives all-chart budgets"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under closedness, strict positivity, generation, EB and pure PR, let U be any subset of all original pure labels with diam(D(p))>=delta>0. One finite positive B bounds the actual optimal extensionBudget in every complete chart and every unit direction at every p in U. Frozen pure compactness and strict exposure give a uniform positive gap 1-T(q,r) on all pure pairs at separation delta. Each actual complete chart has a unit diameter axis, and its antipodal comparison is 1-2a. The gap gives 2a>=gamma, hence all actual optimal budgets are at most 1/gamma. The budget is the attained original positive-extension optimum, not a reciprocal definition."))), DescribeRole.Theorem),
            Paragraph(Text("Assume the original arbitrary finite dimensional V, closed generating pointed cone C and linear unit u strictly positive on nonzero C. K is the entire normalized base, P its entire pure locus, D(p) is the entire original exclusion, EB3 holds at every pure label, and PR exchanges only pure endpoints of the full original comparison. No Inj or singleton confirmer hypothesis is required. Under precisely these assumptions p mapped to diam(D(p)) is upper semicontinuous on all P. To see this, fix any real a and a converging sequence pn in the superlevel diam(D(pn))>=a. Compactness of K and NonemptyCompacts.isCompact_subsets_of_isCompact supply a subsequence with a whole compact limit Q. The compact_diameter_lipschitz estimate transfers the threshold to diam(Q). ReciprocalExclusionLimits.exclusion_limit_dichotomy says Q is either the whole D(p) or a pure singleton contained in D(p); in both cases Q is contained in D(p). Metric.diam_mono gives a<=diam(D(p)). The sequential closed-set criterion proves every superlevel closed, which is the full upper-semicontinuity statement.")),
            Describe.Lean(DescribeId.Create("original-local-budget-iff"), DeclarationHandle.Create(Owner + "original_local_budget_iff"),
                H("Whole-P continuity exactly equals finite local optimal budgets"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Under original EB3 and pure PR, Hausdorff continuity at any original pure p is equivalent to an open neighborhood U containing p in all P and a finite positive B bounding every actual chart and unit-direction extensionBudget throughout U. Forward: the exact regular-region theorem gives a neighborhood with a positive whole-diameter lower bound, and original_noncollapse_bounded_budget supplies B. Reverse: original_bounded_budget_noncollapse gives a positive diameter floor on U, placing p inside an actual closed diameter layer and hence in the whole-ball continuity set. No uniqueness or Inj hypothesis is needed."))), DescribeRole.Theorem),
            Paragraph(Text("For the scalar applications below fix exactly the closedness, strict positivity, generation, EB3 and pure PR assumptions just stated. At each p choose any full chart from ballHyp(EB3), and let a(p) be the positive coefficient selected by original_common_chart_scale. Its specification holds in every complete chart, for every unit direction and every mixed coordinate of the entire closed ball; it includes actual confirming effects from the full F(q). Put beta(p)=1/(2a(p)). The same specification proves that beta is feasible, is no larger than every feasible budget and equals extensionBudget in each chart and direction. Thus it is the attained original infimum. For q=b(v) and r=b(-v), the actual mixed-input formula gives a(p)=(1-T(q,r))/2. Chart independence makes this formula agree with the chosen coefficient in every chart. These applications retain the full conclusions of the scalar aggregate; the individual limit arguments are proof-internal applications rather than separately exported theorems.")),
            new DocumentBlock.Section(H("Actual scale across every whole-ball limit"), Blocks(
                Paragraph(Text("For arbitrary original pure labels pn and p under EB3 and pure-only PR, Hausdorff convergence of the entire D(pn) to D(p) forces convergence of the actual common calibration coefficient. The coefficient is selected from original_common_chart_scale and obeys its all-chart, all-mixed-input law. Parameter extraction is reused from ExclusionIncidence.parameter_subsequence. Closedness of the original pure locus makes every limiting sphere point pure; sphere_extreme_injective_or_zero rules out positive rank loss, while nontriviality of the complete limiting ball excludes the zero map. The limiting affine map is therefore an actual full chart of D(p). Its fixed antipodal endpoints recover the same coefficient via (1-T(q,r))/2 and pure joint comparison continuity. No continuity of chosen charts or extra compact-pure premise is assumed.")))),
            new DocumentBlock.Section(H("Actual zero and infinite limits under singleton collapse"), Blocks(
                Paragraph(Text("Every whole-exclusion sequence converging to an actual singleton has calibration tending to zero and actual optimalBudget tending to positive infinity. The latter equals the original attained extensionBudget in every chart and every unit direction; optimalBudget is never accepted solely from its reciprocal definition. Diameter continuity on nonempty compact sets and the general diameter-collapse argument just given yield divergence. For an arbitrary singleton endpoint q in V, continuity of compact diameter gives diam(D(pn)) tending to zero without any label-convergence assumption. Choose one unit direction in each arbitrary full chart, identify its attained budget with beta(pn), and apply the general EB divergence argument. Since a(pn) is the inverse of beta(pn) divided by two, inverse convergence at positive infinity gives a(pn) tending to zero. This result does not assert that any collapse exists.")))),
            new DocumentBlock.Section(H("Both exhaustive original subsequence alternatives"), Blocks(
                Paragraph(Text("Every sequence of original pure labels tending to p has a strictly indexed subsequence on which either the whole exclusions tend to the complete D(p), with calibration and optimal budget tending to their actual values at p, or the whole exclusions tend to a pure singleton q in D(p), with calibration tending to zero and optimal budget to positive infinity. Applying the same theorem to any initial subsequence gives the complete scalar refinement. The whole-ball-or-pure-singleton dichotomy is directly reused from the frozen ReciprocalExclusionLimits owner.")))),
            new DocumentBlock.Section(H("Upper semicontinuity on all original pure labels"), Blocks(
                Paragraph(Text("The actual common calibration is upper semicontinuous on the entire original P. For each scalar superlevel and every converging original label sequence in it, compact whole-set extraction and the exhaustive scalar alternatives force the limiting label into the same superlevel. In the singleton case the threshold is at most zero, and the actual limiting label still has strictly positive calibration. This is neither a P0 restriction nor a chosen-neighborhood statement.")))),
            new DocumentBlock.Section(H("Lower semicontinuity of the actual optimum on all P"), Blocks(
                Paragraph(Text("Every scalar sublevel of the actual attained optimal budget is closed in all original P. The whole branch preserves the sublevel by scalar convergence. The singleton branch is incompatible with a finite upper bound because its actual budgets diverge: eventual beta>=t+1 contradicts the assumed sublevel beta<=t. Every original individual budget remains finite and at least one; infinity is a sequence limit, not the budget assigned to an individual ball.")))),
            new DocumentBlock.Section(H("Every discontinuity retains its actual pure collapse and both scalar limits"), Blocks(
                Paragraph(Text("At every actual Hausdorff discontinuity there is a sequence of original pure labels tending to p and an original pure q in D(p) such that the entire moving exclusions tend to q, their actual calibrations tend to zero and their actual optimal budgets tend to positive infinity. The actual discontinuity-collapse theorem supplies pn tending to p and a pure q in the old whole D(p); converting its Hausdorff-distance conclusion to convergence of nonempty compact sets permits the singleton application above. Both zero and positive-infinity scalar limits therefore hold on this same actual sequence. No collapse existence or exclusion is inferred.")))),
            Describe.Lean(DescribeId.Create("original-common-continuity-sets"), DeclarationHandle.Create(Owner + "original_common_continuity_sets"),
                H("Exact common continuity sets and all-P local optimal budgets"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("The original regular region R equals the continuity sets of the whole Hausdorff map D, the actual calibration a and the actual optimal budget beta. The result also gives the exact open-neighborhood local-budget equivalence in all P, uniform boundedness on every compact subset of R, positivity and the half-scale upper bound, and attained sharpness of beta in every actual chart and unit direction. At an irregular label the actual collapse witness has a tending to zero and beta to infinity, whereas a(p) is positive and beta(p) finite. For the scalar-to-whole continuity converse, an actual discontinuity supplies pn tending to p with a(pn) tending to zero. Continuity of a would force a(p)=0, contradicting its strict positivity. Continuity of beta gives continuity of a=1/(2 beta), since beta(p)>0, and yields the same contradiction. Whole continuity gives scalar continuity by the whole-limit application and continuity of the reciprocal at positive a(p). Hence these are exactly the same R, not just intersecting continuity sets. To pass between local scalar bounds and all-chart budgets, use the attained equality extensionBudget=beta in every chart; the converse chooses a unit direction in one full positive-dimensional chart. On any compact S contained in this same R, beta is continuous on S, so its compact image is bounded above. This yields a finite bound depending on S and supplies no global finite bound on P. The open dense R and closed nowhere-dense Sigma follow from the compact Baire application to the closed positive-diameter layers described here. Inj and singleton full-zero confirmer hypotheses are absent here and remain confined to OriginalRowSaturation and its normal-family prerequisites."))), DescribeRole.Theorem))));
}
